DROP VIEW IF EXISTS `HumanResources_vEmployeeDepartmentHistory`;
CREATE VIEW `HumanResources_vEmployeeDepartmentHistory` AS
select `e`.`BusinessEntityID` AS `BusinessEntityID`,`p`.`Title` AS `Title`,`p`.`FirstName` AS `FirstName`,`p`.`MiddleName` AS `MiddleName`,`p`.`LastName` AS `LastName`,`p`.`Suffix` AS `Suffix`,`s`.`Name` AS `Shift`,`d`.`Name` AS `Department`,`d`.`GroupName` AS `GroupName`,`edh`.`StartDate` AS `StartDate`,`edh`.`EndDate` AS `EndDate` from ((((`adventureworks`.`HumanResources_Employee` `e` join `adventureworks`.`Person_Person` `p` on((`p`.`BusinessEntityID` = `e`.`BusinessEntityID`))) join `adventureworks`.`HumanResources_EmployeeDepartmentHistory` `edh` on((`e`.`BusinessEntityID` = `edh`.`BusinessEntityID`))) join `adventureworks`.`HumanResources_Department` `d` on((`edh`.`DepartmentID` = `d`.`DepartmentID`))) join `adventureworks`.`HumanResources_Shift` `s` on((`s`.`ShiftID` = `edh`.`ShiftID`)))